  "grundarfjordur.GFB.list.8.occupation": "Kandydat",
  "grundarfjordur.GFB.list.9.occupation": "Kandydat",
  "grundarfjordur.GFB.tagline": "Framsókn i Samfylking — naprzód Grundarfjörður",
  "grundarfjordur.GFD.agenda.0.text": "Wzmacnianie gospodarki i przyciąganie inwestycji do Grundarfjarðar.",
  "grundarfjordur.GFD.agenda.0.title": "Gospodarka",
  "grundarfjordur.GFD.agenda.1.text": "Zwiększenie podaży mieszkań i poprawa warunków mieszkaniowych dla rodzin.",
  "grundarfjordur.GFD.agenda.1.title": "Mieszkalnictwo",
  "grundarfjordur.GFD.agenda.2.text": "Ochrona przyrody i zrównoważone wykorzystanie zasobów regionu.",
  "grundarfjordur.GFD.agenda.2.title": "Ochrona środowiska",
  "grundarfjordur.GFD.list.1.occupation": "Kandydat",
  "grundarfjordur.GFD.list.10.occupation": "Kandydat",
