  "hunabyggd.HBA.list.2.occupation": "Kandydat",
  "hunabyggd.HBA.tagline": "Wszyscy razem — wspólna przyszłość Húnabyggð",
  "hunathing.B.agenda.0.text": "Wspieranie rolników i rolnictwa w Dalnum.",
